// Global SVG arrow markers (hidden, referenced by ExerciseAnim)
function ExerciseAnimDefs() {
  return (
    <svg width="0" height="0" style={{position:"absolute",overflow:"hidden"}}>
      <defs>
        <marker id="eaA" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto">
          <polygon points="0,0 10,5 0,10" fill="#c9a84c"/></marker>
        <marker id="eaU" markerWidth="10" markerHeight="10" refX="5" refY="1" orient="auto">
          <polygon points="0,10 5,0 10,10" fill="#c9a84c"/></marker>
        <marker id="eaD" markerWidth="10" markerHeight="10" refX="5" refY="9" orient="auto">
          <polygon points="0,0 5,10 10,0" fill="#c9a84c"/></marker>
        <marker id="eaL" markerWidth="10" markerHeight="10" refX="1" refY="5" orient="auto">
          <polygon points="10,0 0,5 10,10" fill="#c9a84c"/></marker>
      </defs>
    </svg>
  );
}

